import json
import re
import os
import shutil
import zipfile
from pathlib import Path

from lxml import etree


def stringify(val):
    # Preserve string formatting when already a string.
    if val is None:
        return ""
    if isinstance(val, str):
        return val
    if isinstance(val, bool):
        return "true" if val else "false"
    return str(val)


def flatten_json(obj, prefix=""):
    """Flatten nested JSON into lookup keys.

    - Dict keys join with '.'
    - List indexes use '[i]'

    Examples:
      {"a": {"b": 1}} -> {"a.b": "1"}
      {"items": [{"name": "x"}]} -> {"items[0].name": "x"}

    Also adds the bare prefix key if obj is a scalar.
    """
    out = {}

    def rec(x, pfx):
        if isinstance(x, dict):
            for k, v in x.items():
                k = str(k)
                np = f"{pfx}.{k}" if pfx else k
                rec(v, np)
        elif isinstance(x, list):
            for i, v in enumerate(x):
                np = f"{pfx}[{i}]" if pfx else f"[{i}]"
                rec(v, np)
        else:
            if pfx:
                out[pfx] = stringify(x)

    rec(obj, prefix)
    return out


PLACEHOLDER_RE = re.compile(r"\{\{\s*(.+?)\s*\}\}")


def replace_placeholders_in_text(text, lookup):
    if text is None or "{{" not in text:
        return text, False

    changed = False

    def replacer(match):
        nonlocal changed
        key = match.group(1).strip()
        if key in lookup:
            changed = True
            return stringify(lookup[key])
        return match.group(0)

    new_text = PLACEHOLDER_RE.sub(replacer, text)
    return new_text, (new_text != text)


def localname(tag):
    # tag may be '{uri}name' or 'name'
    if tag is None:
        return ""
    if "}" in tag:
        return tag.split("}", 1)[1]
    return tag


def remove_layout_cache_from_paragraph(p_elem):
    # Templates vary: lineSegArray/lineSeg vs linesegarray/lineseg
    remove_names = {"linesegarray", "lineseg", "linesegarray", "lineseg", "linesegarray"}
    # include camelCase variants too (case-insensitive matching handles it)
    for child in list(p_elem):
        ln = localname(child.tag)
        if ln.lower() in {"linesegarray", "lineseg", "linesegarray", "lineseg", "linesegarray", "lineseg", "linesegarray"}:
            p_elem.remove(child)


def find_parent_paragraph(elem, hp_ns):
    p_tag = f"{{{hp_ns}}}p"
    cur = elem
    while cur is not None:
        if cur.tag == p_tag or localname(cur.tag) == "p":
            return cur
        cur = cur.getparent()
    return None


def process_section_xml(section_path, lookup):
    tree = etree.parse(str(section_path))
    root = tree.getroot()

    nsmap = root.nsmap or {}
    hp_ns = nsmap.get("hp") or nsmap.get(None) or "http://www.hancom.co.kr/hwpml/2010/HWPML"

    modified_paragraphs = set()

    # 1) Simple per <hp:t> replacement
    for t_elem in root.iter(f"{{{hp_ns}}}t"):
        if t_elem.text and "{{" in t_elem.text:
            original = t_elem.text
            new_text, changed = replace_placeholders_in_text(original, lookup)
            if changed:
                t_elem.text = new_text
                p = find_parent_paragraph(t_elem, hp_ns)
                if p is not None:
                    modified_paragraphs.add(p)

    # 2) Handle placeholders split across multiple <hp:t> inside a single <hp:run>
    #    Strategy: concatenate run texts, replace, then store result in first <hp:t>,
    #    blanking subsequent <hp:t> while preserving elements.
    run_tag = f"{{{hp_ns}}}run"
    t_tag = f"{{{hp_ns}}}t"

    for run in root.iter(run_tag):
        t_elems = [c for c in run if c.tag == t_tag]
        if len(t_elems) <= 1:
            continue

        combined = "".join([(te.text or "") for te in t_elems])
        if "{{" not in combined:
            continue

        new_combined, changed = replace_placeholders_in_text(combined, lookup)
        if not changed:
            continue

        t_elems[0].text = new_combined
        for te in t_elems[1:]:
            # Preserve structure but avoid duplicating leftover fragments
            te.text = ""

        p = find_parent_paragraph(run, hp_ns)
        if p is not None:
            modified_paragraphs.add(p)

    # Remove layout-cache elements from modified paragraphs
    for p in modified_paragraphs:
        for child in list(p):
            ln = localname(child.tag)
            if ln.lower() in ("linesegarray", "lineseg"):
                p.remove(child)

    tree.write(str(section_path), xml_declaration=True, encoding="UTF-8")

    # Return some stats for validation
    return {
        "hp_ns": hp_ns,
        "modified_paragraph_count": len(modified_paragraphs),
    }


def main():
    # 1. Load JSON data
    with open("/root/inventory_data.json", "r", encoding="utf-8") as f:
        data = json.load(f)

    # 2. Build a flat lookup dict from JSON
    lookup = {}
    if isinstance(data, dict):
        # Keep top-level keys as-is
        lookup.update({str(k): stringify(v) for k, v in data.items()})
        # Also provide flattened dot/bracket paths in case template uses them
        lookup.update(flatten_json(data))
    else:
        lookup.update(flatten_json(data))

    # 3. Extract the HWPX zip
    template_path = "/root/inventory_report_template.hwpx"
    extract_dir = Path("/tmp/hwpx_work")
    if extract_dir.exists():
        shutil.rmtree(extract_dir)
    extract_dir.mkdir(parents=True)

    with zipfile.ZipFile(template_path, "r") as zf:
        zf.extractall(extract_dir)

    contents_dir = extract_dir / "Contents"
    section_files = sorted(contents_dir.glob("section*.xml"))
    if not section_files:
        raise FileNotFoundError(f"No section*.xml files found under {contents_dir}")

    # Capture original paragraph counts for empty-paragraph preservation check
    original_paragraph_counts = {}
    for sf in section_files:
        tree = etree.parse(str(sf))
        root = tree.getroot()
        nsmap = root.nsmap or {}
        hp_ns = nsmap.get("hp") or nsmap.get(None) or "http://www.hancom.co.kr/hwpml/2010/HWPML"
        p_count = sum(1 for _ in root.iter(f"{{{hp_ns}}}p"))
        original_paragraph_counts[sf.name] = p_count

    # 4-8. Modify all section XML files
    stats = {}
    for sf in section_files:
        stats[sf.name] = process_section_xml(sf, lookup)

    # 7. Verify no {{...}} remain
    remaining = []
    for sf in section_files:
        tree = etree.parse(str(sf))
        root = tree.getroot()
        nsmap = root.nsmap or {}
        hp_ns = nsmap.get("hp") or nsmap.get(None) or "http://www.hancom.co.kr/hwpml/2010/HWPML"
        for t_elem in root.iter(f"{{{hp_ns}}}t"):
            if t_elem.text and "{{" in t_elem.text:
                remaining.append((sf.name, t_elem.text))

    if remaining:
        print("WARNING: Remaining placeholders:")
        for fn, txt in remaining:
            print(f"  - {fn}: {txt}")
    else:
        print("All placeholders replaced successfully.")

    # 9. Repackage as HWPX zip
    output_path = Path("/root/inventory_report_ready.hwpx")
    if output_path.exists():
        output_path.unlink()

    with zipfile.ZipFile(output_path, "w", zipfile.ZIP_DEFLATED) as zf:
        for dirpath, dirnames, filenames in os.walk(extract_dir):
            for filename in filenames:
                filepath = Path(dirpath) / filename
                arcname = filepath.relative_to(extract_dir)
                zf.write(filepath, str(arcname))

    print(f"Output written to {output_path}")

    # Extra: validate paragraph count preservation quickly on the modified worktree
    for sf in section_files:
        tree = etree.parse(str(sf))
        root = tree.getroot()
        nsmap = root.nsmap or {}
        hp_ns = nsmap.get("hp") or nsmap.get(None) or "http://www.hancom.co.kr/hwpml/2010/HWPML"
        new_p_count = sum(1 for _ in root.iter(f"{{{hp_ns}}}p"))
        old_p_count = original_paragraph_counts.get(sf.name)
        if old_p_count is not None and new_p_count != old_p_count:
            print(f"WARNING: Paragraph count changed in {sf.name}: {old_p_count} -> {new_p_count}")


if __name__ == "__main__":
    main()

